pub fn ping(self: Rout) !void { const home = stor.dirzData(self.allo, self.iozz) catch ""; const nowz = spaw.nowzMsec(self.iozz); var uizz_age_seco: i64 = -1; { self.ctxz.relo_mute.lockUncancelable(self.iozz); defer self.ctxz.relo_mute.unlock(self.iozz); if (std.mem.eql(u8, self.quer, "ui=1")) self.ctxz.uizz_seen_msec = nowz else if (std.mem.eql(u8, self.quer, "ui=0")) self.ctxz.uizz_seen_msec = 0; if (self.ctxz.uizz_seen_msec > 0) uizz_age_seco = @divTrunc(nowz - self.ctxz.uizz_seen_msec, 1000); } var body: std.Io.Writer.Allocating = .init(self.allo); const wrtr = &body.writer; try wrtr.writeAll("{\"ok\":true,\"cwd\":"); try std.json.Stringify.encodeJsonString(home, .{}, wrtr); try wrtr.print(",\"platform\":\"{s}\",\"arch\":\"{s}\",\"sep\":", .{ @tagName(builtin.os.tag), @tagName(builtin.cpu.arch) }); try std.json.Stringify.encodeJsonString(std.fs.path.sep_str, .{}, wrtr); try wrtr.print(",\"build\":\"{s}/{s}\",\"version\":\"{s}\",\"shells\":{s},\"reloadAt\":{d},\"jobs\":", .{ @tagName(builtin.mode), builtin.zig_version_string, builOpti.version, self.ctxz.shel_json, self.ctxz.relo_msec }); if (self.ctxz.regz.liveCoun(self.iozz)) |coun| try wrtr.print("{d}", .{coun}) else try wrtr.writeAll("null"); try wrtr.print(",\"uiAgeS\":{d}}}", .{uizz_age_seco}); try http.respSend(self.strm, 200, "OK", body.writer.buffered()); }
