pub fn jobs(self: Rout) !void { var body: std.Io.Writer.Allocating = .init(self.allo); try self.ctxz.regz.jobsWrit(self.iozz, &body.writer); const rawz = body.writer.buffered(); if (rawz.len < 2) return http.respSend(self.strm, 200, "OK", rawz); var outz: std.Io.Writer.Allocating = .init(self.allo); try outz.writer.writeAll(rawz[0 .. rawz.len - 2]); try self.ctxz.sche.chaiJobzWrit(self.iozz, &outz.writer, !std.mem.endsWith(u8, rawz[0 .. rawz.len - 2], "[")); try self.ctxz.sche.manuJobzWrit(self.iozz, &outz.writer, !std.mem.endsWith(u8, outz.writer.buffered(), "[")); try outz.writer.writeAll("]}"); try http.respSend(self.strm, 200, "OK", outz.writer.buffered()); }
pub fn atta(self: Rout) !void { const iden = http.querValu(self.quer, "id") orelse ""; const from = std.fmt.parseInt(u64, http.querValu(self.quer, "from") orelse "0", 10) catch 0; const ring = self.ctxz.regz.ringJobz(self.iozz, iden) orelse self.ctxz.sche.chaiRing(self.iozz, iden) orelse self.ctxz.sche.manuRing(self.iozz, iden) orelse return http.respSend(self.strm, 404, "Not Found", "{\"error\":\"no_such_job\"}"); defer ring.rele(); try self.strm.interface.writeAll(stre.HEAD); try self.strm.interface.flush(); var buff: [64 * 1024]u8 = undefined; var atzz = from; var idle_msec: u32 = 0; var firs = true; while (true) { const gotz = ring.fromRead(self.iozz, atzz, &buff); if (firs and gotz.lost) try stre.erroWrit(&self.strm.interface, "[auto-task: earlier output dropped]\n"); firs = false; if (gotz.byte > 0) { try self.strm.interface.writeAll(buff[0..gotz.byte]); try self.strm.interface.flush(); atzz = gotz.next; idle_msec = 0; continue; } if (gotz.done) return; std.Io.sleep(self.iozz, .fromMilliseconds(CF.atta_msec), .awake) catch return; idle_msec += CF.atta_msec; if (idle_msec >= CF.hear_msec) { try stre.beatWrit(&self.strm.interface); idle_msec = 0; } } }
pub fn kill(self: Rout) !void { const valu = self.bodyJson() orelse return self.erroSend("bad_json"); const iden = jsonStrz(valu, "id") orelse ""; if (iden.len > 0) { const chai_iden = if (std.mem.lastIndexOfScalar(u8, iden, '~')) |atzz| iden[0..atzz] else iden; if (!self.ctxz.sche.chaiAbor(self.iozz, chai_iden)) { if (!self.ctxz.sche.manuAbor(self.iozz, iden)) _ = self.ctxz.regz.idenKill(self.iozz, iden); } } try http.respSend(self.strm, 200, "OK", "{\"ok\":true}"); }
pub fn stdi(self: Rout) !void { const valu = self.bodyJson() orelse return self.erroSend("bad_json"); const jobz_iden = jsonStrz(valu, "jobId") orelse ""; const data = jsonStrz(valu, "data") orelse ""; const newl = jsonBool(valu, "nl") orelse true; const eofz = jsonBool(valu, "eof") orelse false; if (data.len > CF.stdi_maxz) return http.respSend(self.strm, 413, "Payload Too Large", "{\"error\":\"stdin_too_large\"}"); const file = self.ctxz.regz.stdiAcqu(self.iozz, jobz_iden) orelse return http.respSend(self.strm, 404, "Not Found", "{\"error\":\"process not found\"}"); var okay = true; if (data.len > 0 or newl) { const full = if (newl) std.mem.concat(self.allo, u8, &.{ data, "\n" }) catch { self.ctxz.regz.stdiRele(self.iozz, jobz_iden, false); return http.respSend(self.strm, 500, "Internal Server Error", "{\"error\":\"no_memory\"}"); } else data; file.writeStreamingAll(self.iozz, full) catch { okay = false; }; } self.ctxz.regz.stdiRele(self.iozz, jobz_iden, eofz); if (!okay) return http.respSend(self.strm, 410, "Gone", "{\"error\":\"stdin_closed\"}"); try http.respSend(self.strm, 200, "OK", "{\"ok\":true}"); }
pub fn keep(self: Rout) !void { const valu = self.bodyJson() orelse return self.erroSend("bad_json"); const iden = jsonStrz(valu, "id") orelse ""; const keepz = jsonBool(valu, "keep") orelse true; if (!self.ctxz.regz.keepSetz(self.iozz, iden, keepz)) return http.respSend(self.strm, 404, "Not Found", "{\"error\":\"no_such_job\"}"); try http.respSend(self.strm, 200, "OK", "{\"ok\":true}"); }
pub fn fire(self: Rout) !void { const valu = self.bodyJson() orelse return self.erroSend("bad_json"); const iden = jsonStrz(valu, "id") orelse ""; if (iden.len == 0) return self.erroSend("missing_id"); try self.ctxz.sche.mute.lock(self.iozz); var foun = false; var hand = false; for (self.ctxz.sche.arme) |*arme| { if (!std.mem.eql(u8, arme.id, iden)) continue; foun = true; hand = arme.requestHand(); break; } self.ctxz.sche.mute.unlock(self.iozz); if (!foun) return http.respSend(self.strm, 404, "Not Found", "{\"error\":\"no_such_task\",\"hint\":\"id not armed — check it exists and is on\"}"); if (!hand) return http.respSend(self.strm, 409, "Conflict", "{\"error\":\"not_a_hand_task\",\"hint\":\"only type:hand or type:chai can be fired manually\"}"); try http.respSend(self.strm, 200, "OK", "{\"ok\":true,\"queued\":true}"); }
pub fn stepRun(self: Rout) !void { const valu = self.bodyJson() orelse return self.erroSend("bad_json"); const iden = jsonStrz(valu, "id") orelse ""; if (iden.len == 0) return self.erroSend("missing_id"); const tabz = jsonStrz(valu, "tab") orelse ""; const resu = self.ctxz.sche.manuRun(self.iozz, iden, if (tabz.len <= 64) tabz else ""); var body: std.Io.Writer.Allocating = .init(self.allo); const wrtr = &body.writer; switch (resu.code) { .okzz => { try wrtr.writeAll("{\"ok\":true,\"queued\":true,\"id\":"); try std.json.Stringify.encodeJsonString(iden, .{}, wrtr); try wrtr.print(",\"waiting\":{},\"lock\":", .{resu.wait}); try std.json.Stringify.encodeJsonString(resu.lockName(), .{}, wrtr); try wrtr.writeAll("}"); return http.respSend(self.strm, 200, "OK", wrtr.buffered()); }, .bad_id => return self.erroSend("bad_id"), .unknown => return http.respSend(self.strm, 404, "Not Found", "{\"error\":\"unknown_step\",\"hint\":\"not a chain step or task id\"}"), .is_chain => return http.respSend(self.strm, 409, "Conflict", "{\"error\":\"is_chain\",\"hint\":\"a chain is fired with /task/fire\"}"), .chain_run => { try wrtr.writeAll("{\"error\":\"chain_running\",\"chain\":"); try std.json.Stringify.encodeJsonString(resu.chaiName(), .{}, wrtr); try wrtr.writeAll(",\"hint\":\"abort the chain first\"}"); return http.respSend(self.strm, 409, "Conflict", wrtr.buffered()); }, .busy => return http.respSend(self.strm, 409, "Conflict", "{\"error\":\"busy\",\"hint\":\"this step is already running or queued, or the queue is full\"}"), .no_mem => return http.respSend(self.strm, 503, "Service Unavailable", "{\"error\":\"no_memory\"}") } }
pub fn chaiAbor(self: Rout) !void { const valu = self.bodyJson() orelse return self.erroSend("bad_json"); const iden = jsonStrz(valu, "id") orelse ""; if (iden.len == 0) return self.erroSend("missing_id"); if (!self.ctxz.sche.chaiAbor(self.iozz, iden)) return http.respSend(self.strm, 409, "Conflict", "{\"error\":\"not_running\"}"); try http.respSend(self.strm, 200, "OK", "{\"ok\":true}"); }
pub fn blobSave(self: Rout, name: []const u8) !void { const body = self.body orelse return self.erroSend("bad_body"); const valu = std.json.parseFromSliceLeaky(std.json.Value, self.allo, body, .{}) catch return self.erroSend("bad_json"); const deli = std.mem.indexOf(u8, self.quer, "clear=1") != null; try stor.mute_save.lock(self.iozz); defer stor.mute_save.unlock(self.iozz); if (std.mem.eql(u8, name, "config.json")) { var real: usize = 0; if (valu == .object) { var iter = valu.object.iterator(); while (iter.next()) |pair| { if (!std.mem.eql(u8, pair.key_ptr.*, "_v")) real += 1; } } if (real < 2) return http.respSend(self.strm, 200, "OK", "{\"ok\":true,\"skipped\":true}"); if (!deli and listWoulEmpt(self.allo, self.iozz, valu)) return http.respSend(self.strm, 200, "OK", "{\"ok\":true,\"skipped\":true}"); } else if (!deli and outpWoulEmpt(self.allo, self.iozz, valu)) { return http.respSend(self.strm, 200, "OK", "{\"ok\":true,\"skipped\":true}"); } stor.lockSave(self.allo, self.iozz, name, body) catch return http.respSend(self.strm, 500, "Internal Server Error", "{\"error\":\"save_failed\"}"); try http.respSend(self.strm, 200, "OK", "{\"ok\":true}"); }
pub fn confPatc(self: Rout) !void { const body = self.body orelse return self.erroSend("bad_body"); const patc = std.json.parseFromSliceLeaky(std.json.Value, self.allo, body, .{ .allocate = .alloc_always }) catch return self.erroSend("bad_json"); if (patc != .object) return self.erroSend("not_an_object"); const deli = std.mem.indexOf(u8, self.quer, "clear=1") != null; try stor.mute_save.lock(self.iozz); defer stor.mute_save.unlock(self.iozz); const stor_rawz = stor.load(self.allo, self.iozz, "config.json"); var curr = std.json.parseFromSliceLeaky(std.json.Value, self.allo, stor_rawz, .{ .allocate = .alloc_always }) catch std.json.Value{ .object = .empty }; if (curr != .object) curr = .{ .object = .empty }; var appl: usize = 0; var iter = patc.object.iterator(); while (iter.next()) |pair| { const keyz = pair.key_ptr.*; const valu = pair.value_ptr.*; if (!deli and guarChec(keyz) and listEmpt(valu) and !listEmpt(curr.object.get(keyz) orelse .null)) continue; if (valu == .null) { _ = curr.object.orderedRemove(keyz); } else { try curr.object.put(self.allo, keyz, valu); } appl += 1; } if (appl > 0) { try curr.object.put(self.allo, "_v", .{ .integer = 1 }); var outz: std.Io.Writer.Allocating = .init(self.allo); try std.json.Stringify.value(curr, .{}, &outz.writer); stor.lockSave(self.allo, self.iozz, "config.json", outz.writer.buffered()) catch return http.respSend(self.strm, 500, "Internal Server Error", "{\"error\":\"save_failed\"}"); } var resp_buff: [64]u8 = undefined; try http.respSend(self.strm, 200, "OK", std.fmt.bufPrint(&resp_buff, "{{\"ok\":true,\"applied\":{d}}}", .{appl}) catch "{\"ok\":true}"); }
