pub fn driv(self: Rout) !void { var body: std.Io.Writer.Allocating = .init(self.allo); const wrtr = &body.writer; try wrtr.writeAll("{\"path\":\"drives:\",\"parent\":null,\"drives\":["); if (builtin.os.tag == .windows) { var firs = true; var lett: u8 = 'A'; while (lett <= 'Z') : (lett += 1) { var path_buff: [8]u8 = undefined; const path = std.fmt.bufPrint(&path_buff, "{c}:\\", .{lett}) catch continue; var dirz = std.Io.Dir.cwd().openDir(self.iozz, path, .{}) catch continue; dirz.close(self.iozz); if (!firs) try wrtr.writeAll(","); firs = false; try std.json.Stringify.encodeJsonString(path, .{}, wrtr); } } else { try wrtr.writeAll("\"/\""); const home = std.process.Environ.getAlloc(stor.enviLive(), self.allo, stor.HOME_VARZ) catch ""; if (home.len > 1) { try wrtr.writeAll(","); try std.json.Stringify.encodeJsonString(home, .{}, wrtr); } } try wrtr.writeAll("]}"); try http.respSend(self.strm, 200, "OK", body.writer.buffered()); }
